local UIModule = CS.Engine.UI.UIModule

---@class DreamAdventuresUtils
local DreamAdventuresUtils = Class("DreamAdventuresUtils")

---进入活动
function DreamAdventuresUtils.EnterDreamAdventures(excludeIds, parameter, isStack)
    isStack = isStack ~= false
    UIModule.OpenDialog(
            { id = Constants.UITypeIds.ActivityDreamAdventureslDreamAdventuresEntranceAnimation, parameters = parameter },
            excludeIds,
            isStack
    )
end

---获取参数表配置
function DreamAdventuresUtils.GetConfigParamsById(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6192, "DreamAdventuresParamsVo", id)
    if vo == nil then
        printError("食契活动参数表 中未找到 %s", id)
        return 0
    end
    return vo.switch
end



return DreamAdventuresUtils